const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', (req, res, next) => {
  try {
    // Input validation example for an optional `limit` query parameter.
    // Parse and clamp to a safe range instead of trusting raw input.
    let limit = USERS.length;
    if (req.query.limit !== undefined) {
      const parsed = Number(req.query.limit);
      if (!Number.isInteger(parsed) || parsed < 1 || parsed > 100) {
        return res.status(400).json({
          error: 'Invalid "limit": must be an integer between 1 and 100',
        });
      }
      limit = parsed;
    }
    res.json(USERS.slice(0, limit));
  } catch (err) {
    next(err);
  }
});

// --- 404 handler for unmatched routes ---
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// --- Centralized error handler ---
// Logs full error server-side, returns a generic message to the client
// so internal details / stack traces are never leaked.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// --- Server bootstrap with config from environment ---
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// --- Graceful shutdown ---
function shutdown(signal) {
  console.log(`${signal} received, shutting down gracefully`);
  server.close(() => process.exit(0));
  // Force-exit if connections don't drain in time
  setTimeout(() => process.exit(1), 10000).unref();
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

