// Simple application for agent to work on

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// --- Security & hardening middleware ---

// Set secure HTTP response headers (CSP, HSTS, etc.)
app.use(helmet());

// Remove the default header that advertises the tech stack
app.disable('x-powered-by');

// Parse JSON bodies with a size limit to mitigate large-payload DoS attacks
app.use(express.json({ limit: '10kb' }));

// Basic rate limiting to reduce brute-force / abuse risk
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// --- In-memory data (replace with a real data source later) ---

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// --- Routes ---

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json(users);
});

// Example of validating a route parameter before use.
// `:id` must be a positive integer; reject anything else with a 400.
app.get('/users/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'Invalid user id' });
    }

    const user = users.find((u) => u.id === id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    return res.json(user);
  } catch (err) {
    return next(err);
  }
});

// --- 404 handler for unmatched routes ---
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// --- Centralized error-handling middleware ---
// Must have 4 args for Express to treat it as an error handler.
// Avoids leaking stack traces to clients while logging them server-side.
app.use((err, req, res, next) => { // eslint-disable-line no-unused-vars
  console.error(err);
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal server error' : err.message,
  });
});

// --- Server startup & graceful shutdown ---

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Gracefully close connections on termination signals
const shutdown = (signal) => {
  console.log(`${signal} received, shutting down gracefully`);
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

