const express = require('express');
const helmet = require('helmet'); // npm i helmet
const rateLimit = require('express-rate-limit'); // npm i express-rate-limit

const app = express();

// --- Security hardening ---------------------------------------------------

// Set secure HTTP headers (CSP, HSTS, etc.) and remove x-powered-by.
app.use(helmet());
app.disable('x-powered-by');

// Basic rate limiting to mitigate brute-force / DoS.
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per window
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// Parse JSON bodies with a strict size limit to prevent memory exhaustion.
app.use(express.json({ limit: '10kb' }));

// --- Input validation helpers ---------------------------------------------

// Validate that an :id route param is a positive integer.
function validateIdParam(req, res, next) {
  const { id } = req.params;
  // Reject anything that isn't a clean positive integer.
  if (!/^\d+$/.test(id)) {
    return res.status(400).json({ error: 'Invalid id: must be a positive integer' });
  }
  const parsed = Number(id);
  if (!Number.isSafeInteger(parsed) || parsed <= 0) {
    return res.status(400).json({ error: 'Invalid id: out of range' });
  }
  req.validatedId = parsed;
  next();
}

// --- Routes ---------------------------------------------------------------

const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json(USERS);
});

// Example of a validated, input-taking route.
app.get('/users/:id', validateIdParam, (req, res, next) => {
  try {
    const user = USERS.find((u) => u.id === req.validatedId);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  } catch (err) {
    next(err); // delegate to centralized error handler
  }
});

// --- Error handling -------------------------------------------------------

// 404 handler for unmatched routes.
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Centralized error handler. Never leak stack traces or secrets to clients.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log internally (avoid logging request bodies that may contain secrets).
  console.error('Unhandled error:', err.message);
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal server error' : err.message,
  });
});

