// Simple application with hardened error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// --- Security middleware ---
app.use(helmet()); // sets secure HTTP headers (CSP, HSTS, X-Frame-Options, etc.)

// Limit request body size to mitigate payload-based DoS
app.use(express.json({ limit: '10kb' }));

// Basic rate limiting to mitigate brute-force / DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// --- Routes ---

// Wrap async handlers so rejected promises hit the error middleware
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Sample in-memory data source
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Input validation: optional ?id= must be a positive integer
    if (req.query.id !== undefined) {
      const id = Number(req.query.id);
      if (!Number.isInteger(id) || id <= 0) {
        return res.status(400).json({ error: 'Invalid id parameter' });
      }
      const user = USERS.find((u) => u.id === id);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }
      // Avoid leaking email unless explicitly required
      return res.json({ id: user.id, name: user.name });
    }

    res.json(USERS.map((u) => ({ id: u.id, name: u.name })));
  })
);

// --- 404 handler ---
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// --- Centralized error handler (must have 4 args) ---
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error server-side, return a generic message to the client
  console.error(err.stack || err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// --- Server bootstrap & graceful shutdown ---
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unexpected failures so the process doesn't end up in a bad state
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => process.exit(0));
});

module.exports = app;

