// Simple application with security-focused error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { param, validationResult } = require('express-validator');

const app = express();

// --- Security & parsing middleware ---
app.use(helmet()); // sets safe HTTP headers
app.use(express.json({ limit: '10kb' })); // limit body size to reduce DoS risk
app.disable('x-powered-by'); // avoid leaking framework info

// Basic rate limiting to mitigate abuse / brute force
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// --- In-memory data (replace with a real data source) ---
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Helper to surface validation errors consistently
function handleValidation(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Invalid input', details: errors.array() });
  }
  next();
}

// --- Routes ---
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json(users);
});

// Example of validated route param (whole numbers only)
app.get(
  '/users/:id',
  param('id').isInt({ min: 1 }).withMessage('id must be a positive integer'),
  handleValidation,
  (req, res) => {
    const id = Number(req.params.id);
    const user = users.find((u) => u.id === id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  }
);

// --- 404 handler for unknown routes ---
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// --- Centralized error handler (must have 4 args) ---
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full details server-side, return a generic message to the client
  console.error(err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// --- Server startup with graceful shutdown ---
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

function shutdown(signal) {
  console.log(`${signal} received, shutting down gracefully`);
  server.close(() => process.exit(0));
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

